INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (1, 'FI-SW-01', '해수 엔젤피시를 키울 물로 알맞은 것은?', '염소를 빼지 않은 수돗물', '민물과 해수를 하루씩 번갈아 사용', '염도와 상관없이 아무 물이나 사용', '바닷물과 비슷한 염도로 맞춘 인공 해수', 4, '엔젤피시는 바다에 사는 해수어라 비중 약 1.020~1.025로 맞춘 해수가 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (2, 'FI-SW-01', '해수 수조의 물이 증발해 줄었을 때 올바른 보충 방법은?', '염도를 맞춘 해수를 보충한다', '소금만 더 넣는다', '염분이 없는 정제수(민물)를 보충한다', '보충하지 않고 그대로 둔다', 3, '증발하면 물만 날아가고 소금은 남기 때문에, 민물을 채워야 원래 염도가 유지됩니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (3, 'FI-SW-01', '해수 엔젤피시에게 알맞은 수온은?', '약 10~14℃', '약 24~27℃', '약 15~19℃', '약 32~35℃', 2, '열대 바다 출신이라 24~27℃ 정도로 일정하게 유지하는 것이 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (4, 'FI-SW-01', '엔젤피시를 여러 마리 함께 키울 때 주의할 점은?', '어떤 물고기와도 절대 다투지 않는다', '같은 종이나 비슷한 엔젤피시끼리 영역 다툼이 심하다', '많이 넣을수록 스트레스가 줄어든다', '혼자 두면 바로 죽는다', 2, '엔젤피시는 영역성이 강해 같은 수조에는 보통 한 마리만 두거나 합사를 신중히 계획해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (5, 'FI-SW-01', '새로 데려온 물고기를 기존 수조에 넣기 전에 권장되는 것은?', '별도 수조에서 몇 주간 격리하며 관찰한다', '도착하자마자 바로 넣는다', '며칠 동안 먹이를 굶긴다', '수돗물로 몸을 헹군다', 1, '격리(검역) 기간을 두면 백점병 같은 질병이 기존 수조로 퍼지는 것을 막을 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (6, 'FI-SW-01', '몸에 하얀 점이 생기고 바위에 몸을 비비는 증상으로 의심되는 질병은?', '감기', '정상적인 성장 과정', '피부 건조', '백점병', 4, '해수 백점병은 기생충 질환으로 전염이 빠르므로 증상이 보이면 바로 격리하고 치료해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (7, 'FI-SW-01', '엔젤피시의 먹이로 알맞은 것은?', '빵 부스러기', '육지 곤충만', '해조류와 해면 성분이 든 해수어 사료를 중심으로 다양하게', '먹이를 주지 않아도 된다', 3, '야생에서 해면과 해조류를 먹기 때문에 이를 포함한 전용 사료와 냉동 먹이를 골고루 주는 것이 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (8, 'FI-SW-01', '산호를 키우는 수조에 엔젤피시를 넣을 때 주의할 점은?', '산호가 엔젤피시를 잡아먹는다', '산호가 더 빨리 자라게 돕는다', '산호를 쪼아 먹을 수 있다', '아무 영향이 없다', 3, '많은 엔젤피시가 산호의 폴립을 쪼아 먹기 때문에 산호 수조에는 신중히 들여야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (9, 'FI-SW-01', '잘 관리한 해수 엔젤피시의 수명은?', '약 1개월', '10년 이상', '약 1년', '100년 이상', 2, '좋은 환경에서는 10년 이상 살 수 있어 오랜 기간 관리할 준비가 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (10, 'FI-SW-01', '수조에서 배설물과 남은 먹이가 분해될 때 생기는, 물고기에게 해로운 물질은?', '암모니아', '산소', '칼슘', '소금', 1, '암모니아는 여과 박테리아가 덜 해로운 물질로 바꿔 주므로, 여과기와 박테리아가 자리 잡은 뒤(물잡이) 물고기를 넣어야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (11, 'FI-SW-02', '뱀상어(타이거 샤크)가 다 자랐을 때 몸길이는?', '약 30cm', '약 1m', '약 20m', '약 3~5m', 4, '뱀상어는 대형 상어로 다 자라면 3~5m에 이릅니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (12, 'FI-SW-02', '뱀상어 이름에 타이거가 붙은 이유는?', '호랑이처럼 소리를 내서', '육지에서도 살 수 있어서', '몸에 털이 나 있어서', '어릴 때 몸에 호랑이 같은 줄무늬가 있어서', 4, '어린 개체는 줄무늬가 뚜렷하고, 자라면서 점점 옅어집니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (13, 'FI-SW-02', '뱀상어를 가정 수조에서 키우는 것에 대한 설명으로 옳은 것은?', '작은 어항으로도 평생 키울 수 있다', '금붕어와 같은 환경이면 충분하다', '다 자라면 너무 커서 일반 가정 수조로는 키울 수 없다', '물 없이도 키울 수 있다', 3, '대형 공공 아쿠아리움 수준의 시설이 필요하므로, 구매 전에 성체 크기와 시설을 반드시 확인해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (14, 'FI-SW-02', '상어의 이빨에 대한 설명으로 옳은 것은?', '한 번 빠지면 다시 나지 않는다', '평생 계속 빠지고 새로 난다', '이빨이 전혀 없다', '사람처럼 32개로 정해져 있다', 2, '상어는 이빨이 여러 줄로 나 있어 빠지면 뒷줄의 이빨이 앞으로 나옵니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (15, 'FI-SW-02', '상어의 뼈대는 무엇으로 이루어져 있나?', '연골', '단단한 뼈(경골)', '뼈가 전혀 없다', '몸 바깥의 껍데기(외골격)', 1, '상어는 연골어류로, 뼈대가 가볍고 유연한 연골로 되어 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (16, 'FI-SW-02', '상어가 먹이가 내는 약한 전기 신호를 감지하는 기관은?', '로렌치니 기관', '아가미', '꼬리지느러미', '비늘', 1, '머리 쪽에 있는 로렌치니 기관으로 숨어 있는 먹이의 전기 신호까지 감지합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (17, 'FI-SW-02', '상어와 가오리를 치료할 때 특히 주의해야 하는 약품 성분은?', '비타민', '소금', '어떤 성분이든 상관없다', '구리', 4, '상어와 가오리는 구리 성분에 매우 민감해, 일반 해수어용 구리 약품이 치명적일 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (18, 'FI-SW-02', '뱀상어의 먹이 습성으로 옳은 것은?', '해초만 먹는 초식성', '플랑크톤만 걸러 먹는다', '물고기, 거북, 바닷새 등 거의 무엇이든 먹는 육식성', '먹이를 먹지 않는다', 3, '뱀상어는 먹이를 가리지 않기로 유명한 대형 포식자입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (19, 'FI-SW-02', '계속 헤엄치는 상어를 위한 수조로 알맞은 것은?', '좁고 높은 원통형 수조', '모서리가 없고 넓은 원형·타원형 수조', '작은 정육면체 수조', '모양은 상관없다', 2, '헤엄치는 상어는 방향을 틀 공간이 넓어야 해서, 모서리 없는 넓은 수조가 적합합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (20, 'FI-SW-02', '크게 자란 물고기를 더 이상 키울 수 없을 때 올바른 행동은?', '가까운 강이나 바다에 풀어 준다', '전문 기관이나 분양처와 상의해 책임 있게 보낸다', '하수구에 흘려보낸다', '먹이를 끊는다', 2, '함부로 방류하면 생태계를 해치고 불법일 수 있어, 반드시 책임 있는 방법을 찾아야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (21, 'FI-FW-01', '잘 관리한 비단잉어(코이)의 수명은?', '수십 년', '1~2년', '약 3개월', '약 5년', 1, '코이는 좋은 환경에서 수십 년을 살 수 있어 오랜 기간 함께할 준비가 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (22, 'FI-FW-01', '다 자란 코이의 크기로 알맞은 것은?', '약 5cm', '약 15cm', '약 3m', '60cm 이상까지 자랄 수 있다', 4, '코이는 크게 자라는 물고기로, 60~90cm까지 자라기도 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (23, 'FI-FW-01', '코이를 키우기에 알맞은 환경은?', '작은 어항', '컵이나 그릇', '넓고 깊은 연못이나 대형 수조', '해수 수조', 3, '크게 자라고 배설물이 많아, 물의 양이 충분하고 여과가 잘 되는 연못이 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (24, 'FI-FW-01', '수온이 많이 내려가는 겨울에 코이에게 먹이를 주는 방법은?', '평소보다 두 배로 준다', '매일 같은 양을 그대로 준다', '수온이 약 10℃ 아래로 떨어지면 먹이를 줄이거나 멈춘다', '따뜻한 물을 부어 수온을 올린 뒤 많이 준다', 3, '수온이 낮으면 소화 능력이 떨어져, 남은 먹이가 소화되지 않고 수질을 해칠 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (25, 'FI-FW-01', '코이 연못에 꼭 필요한 장비는?', '히터만', '여과기와 산소 공급 장치', '조명만', '아무 장비도 필요 없다', 2, '코이는 배설물이 많고 산소를 많이 쓰기 때문에 여과와 산소 공급이 필수입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (26, 'FI-FW-01', '코이에게 알맞은 먹이는?', '코이 전용 사료와 약간의 채소', '빵', '사람이 먹다 남긴 음식', '먹이를 주지 않아도 된다', 1, '코이는 잡식성이지만 빵이나 사람 음식은 영양이 맞지 않고 수질을 쉽게 해칩니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (27, 'FI-FW-01', '겨울에 연못 수면이 얼 때 주의할 점은?', '얼음을 망치로 세게 깨뜨린다', '수면을 완전히 덮어 막는다', '신경 쓰지 않아도 된다', '수면 전체가 얼지 않도록 일부를 열어 둔다', 4, '수면이 다 얼면 물속 가스가 빠지지 못합니다. 얼음을 세게 깨면 충격이 물고기에게 전해지므로 피해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (28, 'FI-FW-01', '새 코이를 연못에 넣을 때 올바른 방법은?', '봉지에서 바로 쏟아붓는다', '수돗물에 한 번 헹군 뒤 넣는다', '뜨거운 물에 잠깐 담근다', '봉지째 물에 띄워 수온을 서서히 맞춘 뒤 넣는다', 4, '수온이 갑자기 바뀌면 큰 스트레스를 받기 때문에 서서히 적응시켜야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (29, 'FI-FW-01', '새로 들인 코이를 바로 기존 연못에 넣으면 안 되는 이유는?', '기존 코이가 질투해서', '물 색이 변해서', '코이 헤르페스 같은 전염병이 퍼질 수 있어서', '이유가 없다', 3, '코이 헤르페스 바이러스는 전염성이 강해, 새 개체는 따로 격리해 관찰한 뒤 합사합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (30, 'FI-FW-01', '야외 연못 위에 그물을 치는 이유는?', '물고기가 하늘로 날아가지 않게', '새나 고양이 같은 포식자로부터 보호하려고', '햇빛을 완전히 막으려고', '물 온도를 높이려고', 2, '왜가리 같은 새나 고양이가 코이를 잡아갈 수 있어 그물로 막아 줍니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (31, 'FI-FW-02', '잘 키운 금붕어의 수명은?', '10년 이상', '몇 주', '약 1년', '100년 이상', 1, '금붕어는 좋은 환경에서 10년 넘게 살 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (32, 'FI-FW-02', '작고 둥근 어항이 금붕어에게 적합하지 않은 이유는?', '물이 적어 수질이 빨리 나빠지고 공간이 부족해서', '금붕어가 둥근 모양을 싫어해서', '물이 너무 깨끗해져서', '적합하지 않은 이유가 없다', 1, '금붕어는 배설물이 많아, 물의 양이 적으면 암모니아가 빨리 쌓입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (33, 'FI-FW-02', '금붕어가 처음 길러진 나라는?', '호주', '브라질', '노르웨이', '중국', 4, '금붕어는 중국에서 붕어를 오랫동안 개량해 만들어졌습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (34, 'FI-FW-02', '수돗물을 금붕어 어항에 쓸 때 올바른 방법은?', '받은 즉시 바로 붓는다', '뜨거운 물을 섞어 붓는다', '물갈이제를 쓰거나 받아 두어 염소를 없앤 뒤 쓴다', '소금을 많이 넣는다', 3, '수돗물의 염소는 아가미를 상하게 하므로 반드시 제거해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (35, 'FI-FW-02', '금붕어 어항 물갈이로 알맞은 방법은?', '매일 물을 전부 바꾼다', '일주일에 한 번 정도 전체의 20~30%만 바꾼다', '물을 절대 바꾸지 않는다', '1년에 한 번 전부 바꾼다', 2, '한 번에 물을 다 바꾸면 수질이 급변하고 유익한 박테리아가 사라집니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (36, 'FI-FW-02', '금붕어 먹이 양으로 알맞은 것은?', '먹을 때까지 계속 준다', '몇 분 안에 다 먹을 만큼, 하루 1~2번', '어항 바닥을 덮을 만큼 한 번에 준다', '일주일에 한 번만 준다', 2, '남은 먹이는 썩어서 수질을 해치므로 적당히 주는 것이 중요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (37, 'FI-FW-02', '금붕어에게 알맞은 수온은?', '약 18~24℃', '약 5℃ 이하', '약 30~35℃', '약 40℃', 1, '금붕어는 열대어보다 조금 낮은 온도를 좋아하고, 수온이 갑자기 바뀌는 것을 싫어합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (38, 'FI-FW-02', '금붕어가 수면에서 계속 입을 뻐끔거리면 의심할 수 있는 것은?', '배가 너무 불러서', '노래를 하고 있어서', '정상적인 놀이', '물속 산소 부족이나 수질 악화', 4, '산소가 부족하면 수면 가까이 올라와 숨을 쉬려 하므로 산소 공급과 수질을 확인해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (39, 'FI-FW-02', '금붕어 지느러미 끝이 하얗게 해지고 녹아내리는 증상의 주된 원인은?', '정상적인 털갈이', '햇빛을 너무 많이 받아서', '수질 악화로 생기는 지느러미 썩음병', '먹이를 적게 먹어서', 3, '지느러미 썩음병은 세균 감염으로, 수질을 개선하고 필요하면 치료해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (40, 'FI-FW-02', '금붕어의 기억력에 대한 설명으로 옳은 것은?', '3초만 기억한다', '아무것도 기억하지 못한다', '몇 달 이상 기억할 수 있다', '1초도 기억하지 못한다', 3, '연구에 따르면 금붕어는 먹이 시간이나 소리를 몇 달 동안 기억할 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (41, 'K9-BD-01', '불독이 더위에 특히 약한 이유는?', '털이 매우 길어서', '주둥이가 짧은 단두종이라 숨으로 열을 식히기 어려워서', '물을 마시지 않아서', '더위에 약하지 않다', 2, '개는 헐떡이며 체온을 식히는데, 주둥이가 짧으면 이 과정이 잘 안 돼 열사병에 걸리기 쉽습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (42, 'K9-BD-01', '여름철 불독 산책으로 알맞은 것은?', '서늘한 아침이나 저녁에 짧게 한다', '한낮에 오래 뛰게 한다', '뜨거운 아스팔트 위를 오래 걷는다', '여름에는 물도 주지 않는다', 1, '더운 시간대를 피하고, 숨이 거칠어지면 바로 쉬게 해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (43, 'K9-BD-01', '불독 얼굴 주름 관리로 알맞은 것은?', '주름은 절대 만지지 않는다', '주름 사이에 물을 고이게 둔다', '로션을 두껍게 발라 둔다', '주름 사이를 자주 닦고 잘 말려 준다', 4, '주름 사이에 습기와 이물질이 쌓이면 피부염이 생기기 쉽습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (44, 'K9-BD-01', '불독과 물놀이를 할 때 주의할 점은?', '모든 개는 수영을 잘하므로 걱정 없다', '물에 넣으면 털이 길어진다', '물을 무서워하지 않으면 혼자 둬도 된다', '몸이 무겁고 다리가 짧아 물에 잘 뜨지 못한다', 4, '불독은 체형상 수영이 어려워, 물가에서는 구명조끼를 입히고 눈을 떼지 말아야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (45, 'K9-BD-01', '잉글리시 불독의 평균 수명은?', '약 2~3년', '약 20~25년', '약 8~10년', '약 40년', 3, '불독은 다른 견종보다 수명이 짧은 편이라 정기 건강검진이 중요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (46, 'K9-BD-01', '불독에게 비만이 특히 위험한 이유는?', '털 색이 변해서', '관절과 호흡에 더 큰 부담을 줘서', '키가 커져서', '위험하지 않다', 2, '원래 호흡이 어려운 견종이라 살이 찌면 호흡 곤란과 관절 질환이 심해집니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (47, 'K9-BD-01', '불독이 심하게 코를 골고 숨소리가 거칠다면?', '단두종 호흡기 질환일 수 있으니 수의사와 상담한다', '정상이니 무시한다', '운동을 더 많이 시킨다', '물을 주지 않는다', 1, '단두종 호흡기 증후군은 수술이 필요할 수도 있어, 증상이 심하면 진료를 받아야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (48, 'K9-BD-01', '불독의 원산지는?', '영국', '멕시코', '일본', '이집트', 1, '불독은 영국에서 유래했습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (49, 'K9-BD-01', '불독이라는 이름의 유래는?', '황소처럼 풀을 먹어서', '황소만큼 커서', '황소 농장에서 처음 태어나서', '과거 황소와 싸우게 하는 경기에 쓰여서', 4, '예전 잔인한 황소 싸움 경기에서 이름이 붙었고, 이후 온순한 반려견으로 개량되었습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (50, 'K9-BD-01', '불독 출산에 대한 설명으로 옳은 것은?', '항상 혼자 쉽게 출산한다', '한 번에 20마리 이상 낳는다', '머리가 커서 제왕절개로 출산하는 경우가 많다', '알을 낳는다', 3, '불독은 자연 분만이 어려운 경우가 많아, 번식에는 수의사의 관리가 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (51, 'K9-PO-02', '푸들 털의 특징으로 옳은 것은?', '1년에 한 번 모두 빠진다', '잘 빠지지 않고 계속 자라서 정기적인 미용이 필요하다', '털이 자라지 않는다', '털이 없다', 2, '푸들 털은 곱슬이고 계속 자라기 때문에 몇 주마다 미용이 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (52, 'K9-PO-02', '푸들 털을 오래 빗지 않으면 생기는 문제는?', '털이 저절로 곧게 펴진다', '털이 엉켜 뭉치고 피부병이 생길 수 있다', '털 색이 바뀐다', '아무 문제도 없다', 2, '엉킨 털은 피부를 당기고 통풍을 막아 피부 질환의 원인이 됩니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (53, 'K9-PO-02', '푸들의 크기 구분으로 옳은 것은?', '스탠더드, 미니어처, 토이 등으로 나뉜다', '한 가지 크기만 있다', '대형견만 있다', '크기가 매일 바뀐다', 1, '같은 푸들이라도 크기에 따라 필요한 공간과 운동량이 다릅니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (54, 'K9-PO-02', '푸들의 성향과 필요한 관리로 알맞은 것은?', '하루 종일 잠만 자서 놀이가 필요 없다', '사람을 싫어해 혼자 두는 것이 좋다', '운동하면 병에 걸린다', '영리하고 활발해서 매일 산책과 놀이가 필요하다', 4, '푸들은 지능이 높아 운동과 함께 머리를 쓰는 놀이도 해 주면 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (55, 'K9-PO-02', '푸들 귀 관리가 중요한 이유는?', '귀로 숨을 쉬어서', '귀가 자주 떨어져서', '귀가 덮여 있고 귓속 털이 많아 외이염이 생기기 쉬워서', '중요하지 않다', 3, '귀가 덮여 통풍이 안 되면 염증이 생기기 쉬워 정기적으로 귀를 청소해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (56, 'K9-PO-02', '토이 푸들처럼 작은 개에게 흔한 관절 질환은?', '피부 각질증', '날개 골절', '슬개골 탈구', '꼬리 탈모', 3, '무릎뼈가 제자리에서 빠지는 질환으로, 높은 곳에서 뛰어내리지 않게 하고 미끄럼 방지 매트를 깔아 주면 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (57, 'K9-PO-02', '푸들 눈 주변이 붉게 물드는 눈물 자국 관리로 알맞은 것은?', '눈물을 그대로 둔다', '눈 주변을 자주 닦아 깨끗하고 건조하게 유지한다', '눈에 직접 비누칠을 한다', '털을 염색한다', 2, '눈물이 계속 젖어 있으면 착색과 피부염이 생길 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (58, 'K9-PO-02', '푸들의 평균 수명은?', '약 12~15년', '약 3년', '약 5년', '약 30년', 1, '푸들은 비교적 오래 사는 견종이라 오랜 기간 함께할 준비가 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (59, 'K9-PO-02', '푸들이 원래 했던 일은?', '양을 지키는 목양견', '썰매를 끄는 썰매견', '집을 지키는 경비견', '물에서 사냥감을 물어 오는 사냥개', 4, '푸들은 원래 물가 사냥에서 활약하던 워터 리트리버였습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (60, 'K9-PO-02', '사람과의 교감을 좋아하는 푸들을 오래 혼자 두면 생길 수 있는 문제는?', '키가 커진다', '털이 빠지지 않는다', '아무 문제도 없다', '분리불안', 4, '분리불안이 생기면 짖음이나 물건 파괴로 이어질 수 있어, 혼자 있는 시간을 서서히 늘려 적응시켜야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (61, 'K9-DL-01', '달마시안 강아지는 태어날 때 어떤 모습일까?', '태어날 때부터 점이 모두 있다', '검은색으로 태어난다', '거의 하얀색이고 자라면서 점이 생긴다', '점이 평생 생기지 않는다', 3, '달마시안의 점은 생후 몇 주부터 나타나기 시작합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (62, 'K9-DL-01', '달마시안에게 유전적으로 흔해 주의해야 하는 질환은?', '날개 기형', '선천성 청각 장애', '털이 자라지 않는 병', '꼬리가 두 개 생기는 병', 2, '달마시안은 청각 장애 비율이 높아, 분양 전에 청력 검사를 확인하는 것이 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (63, 'K9-DL-01', '달마시안이 요로 결석에 잘 걸리는 이유와 관리법은?', '요산을 잘 분해하지 못해서, 물을 충분히 먹이고 식단을 관리한다', '물을 너무 많이 마셔서, 물을 줄인다', '운동을 많이 해서, 운동을 금지한다', '요로 결석에 걸리지 않는다', 1, '달마시안은 요산이 소변에 많이 섞여 결석이 생기기 쉬워 수분 섭취와 식단 관리가 중요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (64, 'K9-DL-01', '달마시안의 운동량으로 알맞은 것은?', '매우 많아서 매일 충분한 운동이 필요하다', '거의 필요 없다', '일주일에 한 번이면 충분하다', '운동하면 안 된다', 1, '체력이 매우 좋은 견종이라 운동이 부족하면 스트레스를 받습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (65, 'K9-DL-01', '달마시안이 과거에 맡았던 대표적인 일은?', '물속 사냥', '썰매 끌기', '양 떼 몰기', '마차 옆을 달리며 마차를 호위하는 일', 4, '마차를 따라 오래 달리던 견종이라 지구력이 뛰어나고, 소방 마차와 함께해 소방서의 상징이 되기도 했습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (66, 'K9-DL-01', '달마시안의 털 관리로 알맞은 것은?', '털이 전혀 빠지지 않는다', '매일 털을 깎는다', '털이 짧지만 많이 빠져 자주 빗질한다', '털 관리가 필요 없다', 3, '짧은 털이 1년 내내 많이 빠지는 편이라 빗질로 관리해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (67, 'K9-DL-01', '달마시안의 평균 수명은?', '약 2년', '약 11~13년', '약 5년', '약 30년', 2, '달마시안은 중대형견으로 평균 11~13년 정도 삽니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (68, 'K9-DL-01', '달마시안이라는 이름이 유래한 지역은?', '멕시코', '크로아티아의 달마티아 지방', '일본', '캐나다', 2, '달마시안은 지금의 크로아티아 달마티아 지방에서 이름이 유래했습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (69, 'K9-DL-01', '달마시안 강아지 시기에 꼭 필요한 것은?', '다양한 사람과 환경을 경험하게 하는 사회화', '사람을 전혀 만나지 않게 하기', '집 밖에 나가지 않기', '혼자 오래 두기', 1, '어릴 때 사회화가 잘 되어야 낯선 사람과 환경에 차분하게 반응합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (70, 'K9-DL-01', '활동량이 많은 달마시안이 운동을 충분히 못 하면 생기기 쉬운 문제는?', '털 색이 진해진다', '키가 줄어든다', '아무 문제도 없다', '물건 파괴나 과도한 짖음 같은 문제 행동', 4, '남는 에너지가 문제 행동으로 이어지고, 이것이 파양의 원인이 되기도 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (71, 'K9-RT-01', '골든 리트리버가 원래 했던 일은?', '썰매 끌기', '집 지키기', '사냥에서 떨어진 새를 물어 오는 일', '양 떼 몰기', 3, '리트리버(Retriever)라는 이름도 물어 온다는 뜻에서 왔습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (72, 'K9-RT-01', '골든 리트리버 털 관리로 알맞은 것은?', '털이 빠지지 않는다', '털을 매일 바짝 깎는다', '털이 이중모라 많이 빠져 자주 빗질한다', '관리할 필요가 없다', 3, '속털과 겉털이 있는 이중모라 특히 털갈이 때 털이 많이 빠집니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (73, 'K9-RT-01', '골든 리트리버에게 유전적으로 흔한 관절 질환은?', '날개 탈구', '고관절 이형성증', '꼬리 골절', '부리 기형', 2, '엉덩이 관절이 제대로 발달하지 않는 질환으로, 체중 관리와 적절한 운동이 중요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (74, 'K9-RT-01', '골든 리트리버의 평균 수명은?', '약 10~12년', '약 2년', '약 5년', '약 25년', 1, '대형견은 소형견보다 수명이 짧은 편입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (75, 'K9-RT-01', '물놀이를 좋아하는 골든 리트리버의 물놀이 후 관리로 알맞은 것은?', '귀에 물을 더 넣어 준다', '털을 젖은 채로 둔다', '관리할 필요가 없다', '귀 안을 잘 말려 외이염을 예방한다', 4, '덮인 귀에 습기가 남으면 외이염이 생기기 쉽습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (76, 'K9-RT-01', '골든 리트리버에게 정기 건강검진이 특히 중요한 이유는?', '키가 매년 자라서', '털 색이 자주 바뀌어서', '중요하지 않다', '암 발생률이 높은 견종이라 조기 발견이 중요해서', 4, '골든 리트리버는 암 발생 비율이 높은 편이라 정기 검진으로 일찍 발견하는 것이 중요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (77, 'K9-RT-01', '다 자란 골든 리트리버의 몸무게는?', '약 3kg', '약 10kg', '약 25~34kg', '약 80kg', 3, '대형견이라 넓은 공간과 충분한 운동이 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (78, 'K9-RT-01', '성장기 골든 리트리버 강아지 운동에서 주의할 점은?', '최대한 오래 달리게 한다', '관절이 약하므로 무리한 점프나 긴 달리기를 피한다', '계단을 하루 종일 오르내리게 한다', '운동을 아예 시키지 않는다', 2, '뼈와 관절이 자라는 시기에 무리하면 관절 질환 위험이 커집니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (79, 'K9-RT-01', '개에게 주면 위험한 음식은?', '초콜릿과 포도', '개 전용 사료', '깨끗한 물', '익힌 닭 가슴살 약간', 1, '초콜릿의 테오브로민과 포도는 개에게 중독을 일으킬 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (80, 'K9-RT-01', '식탐이 있는 골든 리트리버의 체중 관리로 알맞은 것은?', '정해진 양만 주고 간식도 조절한다', '달라는 대로 계속 준다', '사람 음식을 자주 준다', '체중은 신경 쓰지 않는다', 1, '비만은 관절 질환과 여러 질병의 위험을 높입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (81, 'K9-RT-02', '래브라도 리트리버가 살찌기 쉬운 이유와 관리법은?', '물을 많이 마셔서 물을 줄인다', '털이 많아서 털을 깎는다', '살이 찌지 않는 견종이다', '식욕이 왕성해서 급여량을 정해 조절한다', 4, '래브라도는 먹는 것을 매우 좋아해 쉽게 비만이 되므로 급여량 관리가 중요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (82, 'K9-RT-02', '래브라도 리트리버의 원산지는?', '멕시코', '중국', '캐나다 뉴펀들랜드', '호주', 3, '래브라도는 캐나다 뉴펀들랜드 지역의 개를 영국에서 개량한 견종입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (83, 'K9-RT-02', '래브라도 털의 특징으로 옳은 것은?', '털이 없다', '짧고 촘촘한 이중모로 물을 잘 막아 준다', '바닥에 끌릴 만큼 길다', '1년 내내 전혀 빠지지 않는다', 2, '물에서 일하던 견종이라 털이 물을 잘 튕겨 내고, 털갈이 때 많이 빠집니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (84, 'K9-RT-02', '래브라도가 많이 활약하는 일은?', '썰매견', '시각장애인 안내견과 탐지견', '경주마', '사냥매', 2, '온순하고 영리해서 안내견, 탐지견, 치료견으로 많이 활동합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (85, 'K9-RT-02', '래브라도에게 필요한 운동량은?', '많아서 매일 충분한 산책과 놀이가 필요하다', '거의 필요 없다', '한 달에 한 번이면 된다', '운동하면 안 된다', 1, '활동량이 많아 운동이 부족하면 비만과 문제 행동이 생기기 쉽습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (86, 'K9-RT-02', '래브라도에게 유전적으로 흔한 질환은?', '날개 기형', '비늘 질환', '부리 과다 성장', '고관절·팔꿈치 이형성증', 4, '관절 질환이 흔해서 체중 관리와 정기 검진이 중요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (87, 'K9-RT-02', '래브라도의 평균 수명은?', '약 3년', '약 5년', '약 10~12년', '약 25년', 3, '래브라도는 대형견으로 보통 10~12년 정도 삽니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (88, 'K9-RT-02', '물건을 물어뜯기 좋아하는 래브라도 강아지를 위한 관리로 알맞은 것은?', '아무거나 씹게 둔다', '입을 묶어 둔다', '씹어도 되는 장난감을 주고 위험한 물건은 치운다', '하루 종일 혼자 둔다', 3, '물어 오던 견종이라 입으로 무는 습성이 강해, 안전한 장난감으로 욕구를 풀어 줘야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (89, 'K9-RT-02', '래브라도의 털 색으로 인정되는 것은?', '파랑, 초록, 보라', '검정, 노랑, 초콜릿', '흰색과 검정 점박이만', '빨강 줄무늬만', 2, '래브라도는 검정, 노랑(옐로), 초콜릿 세 가지 색이 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (90, 'K9-RT-02', '수달 꼬리라고도 불리는 래브라도의 굵은 꼬리가 하는 역할은?', '수영할 때 방향을 잡는 키 역할', '물속에서 숨을 쉬는 역할', '먹이를 저장하는 역할', '아무 역할도 없다', 1, '굵고 튼튼한 꼬리가 물속에서 방향을 바꾸는 데 도움을 줍니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (91, 'K9-CW-01', '치와와의 원산지는?', '영국', '캐나다', '이란', '멕시코', 4, '치와와라는 이름은 멕시코의 치와와 주에서 왔습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (92, 'K9-CW-01', '다 자란 치와와의 몸무게는?', '약 10kg', '약 25kg', '약 50kg', '약 1.5~3kg', 4, '치와와는 세계에서 가장 작은 견종 중 하나입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (93, 'K9-CW-01', '몸집이 작은 치와와가 겨울에 특히 주의해야 할 점은?', '추위에 강해 밖에서 재운다', '찬물로 자주 목욕시킨다', '추위에 약해 옷이나 담요로 따뜻하게 해 준다', '난방을 끈다', 3, '몸이 작고 털이 짧아 체온을 쉽게 잃습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (94, 'K9-CW-01', '아주 작은 치와와 강아지가 끼니를 거르면 생길 수 있는 위험은?', '비만', '저혈당', '키가 갑자기 큰다', '아무 문제 없다', 2, '몸에 저장된 에너지가 적어, 오래 굶으면 저혈당으로 쓰러질 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (95, 'K9-CW-01', '치와와 머리를 다룰 때 주의해야 하는 이유는?', '머리뼈의 숫구멍(몰레라)이 완전히 닫히지 않은 경우가 있어서', '머리에 뿔이 있어서', '머리가 매우 단단해서', '주의할 필요가 없다', 1, '숫구멍이 열려 있는 개체는 머리 충격에 특히 약합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (96, 'K9-CW-01', '치와와가 높은 곳에서 자주 뛰어내리면 생기기 쉬운 문제는?', '슬개골 탈구나 골절', '털이 길어진다', '시력이 좋아진다', '아무 문제 없다', 1, '뼈가 가늘고 작아 소파나 침대에서 뛰어내리다 다치기 쉽습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (97, 'K9-CW-01', '입이 작은 치와와에게 특히 중요한 관리는?', '이빨을 깎아 준다', '딱딱한 돌을 씹게 한다', '이빨 관리는 필요 없다', '양치질로 치석과 치주 질환을 예방한다', 4, '작은 입에 이빨이 촘촘해 치석이 생기기 쉽습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (98, 'K9-CW-01', '치와와의 평균 수명은?', '약 3년', '약 6년', '약 14~16년', '약 40년', 3, '치와와는 오래 사는 견종이라 10년 이상 함께할 준비가 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (99, 'K9-CW-01', '경계심이 강한 치와와를 위한 관리로 알맞은 것은?', '사람을 전혀 만나지 않게 한다', '어릴 때부터 사회화 교육을 한다', '짖을 때마다 크게 혼낸다', '아무것도 하지 않는다', 2, '어릴 때 다양한 경험을 하면 과도한 짖음과 공격성을 줄일 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (100, 'K9-CW-01', '몸집이 작은 치와와의 운동으로 알맞은 것은?', '작아서 운동이 필요 없다', '짧더라도 매일 산책과 놀이를 한다', '하루에 5시간 이상 달린다', '실내에만 두고 움직이지 않게 한다', 2, '작은 개도 운동과 바깥 자극이 있어야 몸과 마음이 건강합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (101, 'RP-SN-01', '방울뱀이 꼬리의 방울을 흔드는 이유는?', '소리를 내서 상대에게 경고하려고', '먹이를 부르려고', '잠을 자려고', '꼬리를 말리려고', 1, '방울 소리는 가까이 오지 말라는 경고 신호입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (102, 'RP-SN-01', '방울뱀의 방울은 어떻게 생기나?', '매년 생일마다 하나씩 생긴다', '태어날 때 모두 완성되어 있다', '먹이를 먹을 때마다 생긴다', '허물을 벗을 때마다 마디가 하나씩 늘어난다', 4, '방울 마디 수로 나이를 알 수는 없습니다. 탈피 횟수와 관련 있고, 끝부분이 떨어져 나가기도 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (103, 'RP-SN-01', '방울뱀을 가정에서 키우는 것에 대한 설명으로 옳은 것은?', '누구나 맨손으로 다뤄도 안전하다', '어린이 반려동물로 적합하다', '독사라 매우 위험하고, 많은 지역에서 허가가 필요하거나 금지된다', '허가나 준비가 전혀 필요 없다', 3, '독사는 물리면 생명이 위험할 수 있어 전문 지식, 장비, 법적 허가를 반드시 확인해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (104, 'RP-SN-01', '방울뱀이 어두운 곳에서도 먹이의 체온을 감지하는 기관은?', '꼬리 방울', '혀끝의 이빨', '눈과 콧구멍 사이의 피트 기관', '비늘', 3, '피트 기관으로 주변보다 따뜻한 먹이의 열을 감지합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (105, 'RP-SN-01', '변온동물인 뱀의 사육장 온도로 알맞은 것은?', '전체를 아주 차갑게 한다', '따뜻한 곳과 서늘한 곳이 모두 있게 온도 차이를 둔다', '전체를 50℃ 이상으로 한다', '온도는 신경 쓰지 않는다', 2, '뱀은 스스로 체온을 만들지 못해, 따뜻한 곳과 서늘한 곳을 오가며 체온을 조절합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (106, 'RP-SN-01', '뱀에게 먹이를 줄 때 권장되는 방법은?', '냉동 후 해동한 설치류를 준다', '살아 있는 쥐를 사육장에 넣어 둔다', '사람 음식을 준다', '채소만 준다', 1, '살아 있는 쥐는 오히려 뱀을 물어 다치게 할 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (107, 'RP-SN-01', '뱀이 허물을 벗기 전에 보이는 신호는?', '방울이 사라진다', '몸이 두 배로 커진다', '아무 신호도 없다', '눈이 뿌옇고 푸르스름하게 흐려진다', 4, '탈피 전에는 시야가 흐려져 예민해지므로 가급적 만지지 않는 것이 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (108, 'RP-SN-01', '독사에게 물렸을 때 올바른 대처는?', '입으로 독을 빨아낸다', '상처를 칼로 째서 피를 뺀다', '팔을 끈으로 꽉 묶는다', '움직임을 줄이고 즉시 119에 신고해 병원으로 간다', 4, '입으로 빨거나 꽉 묶으면 오히려 상태가 나빠질 수 있어 빨리 병원으로 가야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (109, 'RP-SN-01', '뱀 사육장 뚜껑에 대한 설명으로 옳은 것은?', '뚜껑 없이 키워도 된다', '뚜껑은 가끔만 닫는다', '작은 틈으로도 빠져나가므로 잠금장치로 단단히 닫는다', '뱀은 탈출하지 않는다', 3, '뱀은 탈출에 능해, 틈이 있으면 쉽게 빠져나갑니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (110, 'RP-SN-01', '허물이 한 번에 벗겨지지 않고 조각조각 남는 주된 원인은?', '먹이를 너무 많이 줘서', '사육장 습도 부족', '조명이 너무 밝아서', '정상이라 신경 쓸 필요 없다', 2, '습도가 낮으면 탈피가 잘 안 되므로 습도를 맞추고 은신처를 마련해 줘야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (111, 'RP-LI-02', '그린 이구아나의 주된 먹이는?', '잎채소 위주의 채소와 약간의 과일', '쥐와 같은 설치류', '개 사료', '곤충만', 1, '그린 이구아나는 초식성이라 동물성 먹이를 주면 건강에 해롭습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (112, 'RP-LI-02', '이구아나 사육장에 UVB 조명이 꼭 필요한 이유는?', '비타민 D3를 만들어 칼슘을 흡수하게 해서', '밤에 잠을 잘 자게 해서', '피부 색을 바꾸려고', '필요 없다', 1, 'UVB가 없으면 칼슘을 흡수하지 못해 뼈가 약해집니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (113, 'RP-LI-02', 'UVB나 칼슘이 부족할 때 이구아나에게 생기는 대표적인 질환은?', '감기', '털 빠짐', '분리불안', '대사성 골질환', 4, '뼈가 약해지고 휘어지는 질환으로, 파충류 사육에서 가장 흔한 문제 중 하나입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (114, 'RP-LI-02', '이구아나가 몸을 데우는 일광욕 장소(바스킹)의 온도는?', '약 10℃', '약 20℃', '약 35℃ 안팎', '약 60℃', 3, '변온동물이라 따뜻한 곳에서 체온을 올려야 소화와 활동이 원활합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (115, 'RP-LI-02', '다 자란 그린 이구아나의 크기는?', '약 10cm', '꼬리까지 1.5m 이상 자랄 수 있다', '약 20cm', '약 5m', 2, '어릴 때는 작지만 크게 자라므로 미리 넓은 사육장을 준비해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (116, 'RP-LI-02', '잘 키운 이구아나의 수명은?', '약 1년', '약 15~20년', '약 3년', '약 100년', 2, '오래 사는 동물이라 장기적으로 돌볼 계획이 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (117, 'RP-LI-02', '이구아나를 다룰 때 꼬리를 잡으면 안 되는 이유는?', '위협을 느끼면 꼬리를 스스로 끊을 수 있어서', '꼬리에 독이 있어서', '꼬리로 숨을 쉬어서', '꼬리를 잡아도 괜찮다', 1, '꼬리가 끊어지면 다시 자라도 원래 모습과 다르므로, 몸통을 받쳐서 다뤄야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (118, 'RP-LI-02', '열대 지방 출신인 이구아나 사육장의 습도는?', '최대한 건조하게 한다', '습도는 상관없다', '물을 주지 않는다', '높게 유지한다', 4, '습도가 낮으면 탈피 문제와 탈수가 생기기 쉬워 습도를 높게 유지해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (119, 'RP-LI-02', '이구아나를 만진 뒤 손을 씻어야 하는 이유는?', '이구아나 독이 묻어서', '손이 초록색으로 변해서', '살모넬라균을 옮길 수 있어서', '씻을 필요 없다', 3, '파충류는 건강해 보여도 살모넬라균을 가지고 있을 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (120, 'RP-LI-02', '이구아나가 머리를 위아래로 끄덕이는 행동의 의미는?', '배가 고프다는 뜻', '잠이 든 상태', '영역 표시나 의사소통', '아무 의미 없다', 3, '머리 흔들기는 영역을 주장하거나 다른 개체에게 신호를 보내는 행동입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (121, 'FL-DSH-01', '맹크스 고양이의 가장 큰 특징은?', '털이 전혀 없다', '꼬리가 없거나 매우 짧다', '귀가 접혀 있다', '다리가 여섯 개다', 2, '맹크스는 꼬리가 없거나 짧은 유전적 특징을 가진 품종입니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (122, 'FL-DSH-01', '맹크스 고양이의 원산지는?', '영국 맨섬', '멕시코', '이란', '태국', 1, '맹크스는 영국과 아일랜드 사이의 맨섬에서 유래했습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (123, 'FL-DSH-01', '맹크스를 키울 때 관찰해야 할 건강 문제는?', '날개 질환', '아가미 질환', '관찰할 것이 없다', '꼬리 없는 유전자와 관련된 척추 이상과 배변 문제', 4, '맹크스 증후군이 있으면 척추와 배변에 문제가 생길 수 있어 수의사 검진이 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (124, 'FL-DSH-01', '맹크스가 토끼처럼 깡충깡충 뛰듯 걷는 이유는?', '꼬리로 균형을 잡아서', '발톱이 없어서', '다리가 아파서', '뒷다리가 앞다리보다 길어서', 4, '긴 뒷다리 때문에 걸음걸이가 독특합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (125, 'FL-DSH-01', '고양이 화장실 개수로 권장되는 것은?', '고양이 수와 상관없이 하나', '고양이 두 마리당 하나', '고양이 수보다 하나 더', '화장실은 필요 없다', 3, '화장실이 부족하거나 더러우면 다른 곳에 실수를 할 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (126, 'FL-DSH-01', '고양이에게 특히 위험한 식물은?', '캣그라스', '백합', '귀리싹', '고양이는 식물에 영향을 받지 않는다', 2, '백합은 꽃가루만 먹어도 고양이에게 급성 신부전을 일으킬 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (127, 'FL-DSH-01', '고양이에게 고양이 전용 사료를 줘야 하는 이유는?', '육식동물이라 타우린 같은 필수 영양소가 꼭 필요해서', '강아지 사료가 더 비싸서', '고양이는 채소만 먹어서', '아무 사료나 줘도 된다', 1, '타우린이 부족하면 심장과 눈에 문제가 생길 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (128, 'FL-DSH-01', '실내에서만 지내는 고양이의 건강 관리로 옳은 것은?', '정기적으로 예방접종과 구충을 한다', '실내 고양이는 병에 걸리지 않는다', '예방접종은 한 번만 하면 평생 충분하다', '아플 때만 병원에 간다', 1, '사람의 옷과 신발로도 병원체가 들어올 수 있어 실내 고양이도 예방이 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (129, 'FL-DSH-01', '고양이에게 스크래처를 마련해 줘야 하는 이유는?', '고양이가 스크래처를 먹어서', '잠자리로만 쓰려고', '필요 없다', '발톱을 다듬고 영역을 표시하는 본능 때문에', 4, '스크래처가 없으면 가구나 벽지를 긁게 됩니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (130, 'FL-DSH-01', '고양이의 평균 수명은?', '약 2년', '약 5년', '약 15년 내외', '약 40년', 3, '고양이는 15년 넘게 함께하는 경우가 많아 오랜 기간 책임질 준비가 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (131, 'FL-DLH-02', '털이 긴 페르시안 고양이에게 매일 빗질이 필요한 이유는?', '털이 금방 짧아져서', '털이 쉽게 엉키고 뭉쳐서', '털 색이 바뀌어서', '필요 없다', 2, '엉킨 털을 그대로 두면 피부가 당기고 피부병이 생길 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (132, 'FL-DLH-02', '얼굴이 납작한 페르시안의 눈 관리로 알맞은 것은?', '눈을 절대 만지지 않는다', '눈물이 많이 흘러 눈 주변을 매일 닦아 준다', '눈에 비누칠을 한다', '관리할 필요가 없다', 2, '얼굴이 납작하면 눈물이 잘 빠지지 않아 눈 주변이 젖고 착색되기 쉽습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (133, 'FL-DLH-02', '페르시안 고양이에게 유전적으로 흔해 검사가 권장되는 질환은?', '다낭성 신장 질환(PKD)', '날개 기형', '아가미 질환', '꼬리 탈모', 1, '신장에 물주머니가 생기는 유전 질환으로, 분양 전 유전자 검사를 확인하는 것이 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (134, 'FL-DLH-02', '페르시안이 더위와 호흡에 약한 이유는?', '털이 짧아서', '물을 마시지 않아서', '더위에 약하지 않다', '얼굴이 납작한 단두종이라 호흡이 어려울 수 있어서', 4, '단두종은 호흡기가 짧아 덥거나 흥분하면 숨쉬기 힘들어할 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (135, 'FL-DLH-02', '고양이가 그루밍하며 삼킨 털을 토해 내는 것을 무엇이라 할까?', '탈피', '털갈이 열', '헤어볼', '구토병', 3, '털이 긴 고양이는 헤어볼이 많이 생겨, 빗질로 삼키는 털을 줄여 주는 것이 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (136, 'FL-DLH-02', '페르시안의 성향으로 알맞은 것은?', '매우 공격적이다', '하루 종일 밖을 뛰어다녀야 한다', '조용하고 온순해 실내 생활에 잘 맞는다', '사람을 전혀 따르지 않는다', 3, '차분한 성격이라 실내에서 키우기 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (137, 'FL-DLH-02', '페르시안 고양이가 유래한 지역은?', '멕시코', '지금의 이란(페르시아) 지역', '캐나다', '영국 맨섬', 2, '페르시아라는 옛 이름에서 품종 이름이 붙었습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (138, 'FL-DLH-02', '털이 긴 고양이의 엉덩이 주변 털을 짧게 다듬어 주는 이유는?', '배변 후 털에 오물이 묻는 것을 막으려고', '꼬리를 짧게 보이려고', '체온을 높이려고', '이유가 없다', 1, '위생 미용을 해 두면 오물이 묻어 피부염이 생기는 것을 막을 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (139, 'FL-DLH-02', '물을 잘 마시지 않는 고양이를 위한 관리로 알맞은 것은?', '물을 아예 치운다', '소금을 먹여 갈증을 유도한다', '신경 쓰지 않는다', '습식 사료나 흐르는 물 급수기로 수분 섭취를 늘린다', 4, '수분이 부족하면 신장과 요로 질환 위험이 커집니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (140, 'FL-DLH-02', '고양이에게 주면 안 되는 음식은?', '고양이 전용 사료', '깨끗한 물', '고양이용 습식 캔', '양파와 마늘', 4, '양파와 마늘은 적혈구를 손상시켜 빈혈을 일으킬 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (141, 'AV-CB-01', '아마존 앵무새의 수명은?', '약 1년', '약 3년', '50년 이상 살 수도 있다', '약 7년', 3, '사람 평생만큼 함께할 수 있어, 데려오기 전에 장기적인 돌봄 계획이 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (142, 'AV-CB-01', '앵무새에게 독성이 있어 주면 안 되는 음식은?', '사과 조각', '아보카도', '익힌 당근', '앵무새 전용 펠릿', 2, '아보카도에는 새에게 치명적인 성분(퍼신)이 들어 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (143, 'AV-CB-01', '무리 생활을 하는 아마존 앵무새에게 필요한 것은?', '매일 충분한 교감과 놀이 시간', '하루 종일 혼자 두기', '어두운 곳에 가둬 두기', '교감은 필요 없다', 1, '사회성이 강해 외로우면 스트레스로 문제 행동이 생깁니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (144, 'AV-CB-01', '앵무새가 스스로 깃털을 뽑는 행동의 원인으로 볼 수 있는 것은?', '스트레스, 지루함, 질병', '정상적인 털갈이', '배가 불러서', '기분이 좋아서', 1, '깃털 뽑기는 건강이나 환경에 문제가 있다는 신호라 수의사 상담과 환경 개선이 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (145, 'AV-CB-01', '앵무새 식단으로 알맞은 것은?', '해바라기씨 같은 씨앗만', '사람 과자', '초콜릿', '펠릿을 중심으로 채소와 과일을 함께', 4, '씨앗만 먹이면 지방이 많고 영양이 부족해집니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (146, 'AV-CB-01', '테플론 코팅 프라이팬을 과열할 때 앵무새가 위험한 이유는?', '소리가 커서', '냄새가 좋아서 과식해서', '나오는 가스가 새에게 치명적이어서', '위험하지 않다', 3, '새의 호흡기는 매우 예민해서, 과열된 코팅 팬의 가스를 마시면 짧은 시간에 숨질 수 있습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (147, 'AV-CB-01', '앵무새 부리와 발톱 관리로 알맞은 것은?', '절대 관리하지 않는다', '씹는 장난감과 다양한 횃대로 자연스럽게 닳게 한다', '매일 가위로 자른다', '부리에 테이프를 감는다', 2, '씹고 오르내리는 활동으로 부리와 발톱이 적당히 닳습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (148, 'AV-CB-01', '아마존 앵무새의 특징으로 알맞은 것은?', '전혀 소리를 내지 않는다', '소리와 말을 흉내 내는 능력이 뛰어나다', '물속에서 산다', '날지 못한다', 2, '말을 잘 따라 하지만 소리도 크기 때문에 소음 문제도 고려해야 합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (149, 'AV-CB-01', '앵무새 케이지 크기로 알맞은 것은?', '날개를 활짝 펴고 움직일 수 있을 만큼 넓게', '몸이 겨우 들어가는 크기', '크기는 상관없다', '케이지 없이 밖에서만', 1, '좁은 케이지는 운동 부족과 스트레스의 원인이 됩니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (150, 'AV-CB-01', '앵무새가 깃털을 부풀리고 웅크린 채 가만히 있다면?', '기분이 좋은 것이니 그대로 둔다', '굶겨서 상태를 본다', '찬물로 목욕시킨다', '아픈 것을 숨기는 습성이 있어 바로 병원에 간다', 4, '새는 아픈 티를 잘 내지 않아, 증상이 보이면 이미 상태가 나쁜 경우가 많습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (151, 'AV-SB-02', '핀치를 키울 때 알맞은 마리 수는?', '반드시 한 마리만 키운다', '마리 수는 상관없다', '무리 생활을 해서 두 마리 이상 함께 키운다', '수십 마리를 작은 새장에 넣는다', 3, '핀치는 무리 지어 사는 새라 혼자 있으면 외로움을 느낍니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (152, 'AV-SB-02', '핀치 새장으로 알맞은 모양은?', '좁고 높은 원통형 새장', '아주 작은 새장', '높이보다 가로로 넓은 새장', '모양은 상관없다', 3, '핀치는 수직보다 수평으로 날아다니기 때문에 가로 공간이 중요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (153, 'AV-SB-02', '핀치의 주식으로 알맞은 것은?', '고기', '작은 씨앗 혼합 사료와 채소', '빵', '초콜릿', 2, '씨앗 사료와 함께 신선한 채소를 주면 영양 균형에 도움이 됩니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (154, 'AV-SB-02', '핀치에게 물을 줄 때 알맞은 방법은?', '매일 깨끗한 물로 바꾸고 목욕할 물도 준다', '일주일에 한 번만 바꾼다', '물을 주지 않는다', '설탕물을 준다', 1, '핀치는 목욕을 좋아하고, 물이 더러우면 병에 걸리기 쉽습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (155, 'AV-SB-02', '핀치의 평균 수명은?', '약 1개월', '약 6개월', '약 50년', '약 5~10년', 4, '작은 새지만 수년간 함께하므로 꾸준한 돌봄이 필요합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (156, 'AV-SB-02', '핀치와 교감하는 방법으로 알맞은 것은?', '매일 손으로 꽉 잡는다', '새장을 흔든다', '큰 소리로 부른다', '억지로 손으로 잡지 않고 지켜보며 돌본다', 4, '핀치는 손에 잡히는 것을 싫어해 억지로 만지면 큰 스트레스를 받습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (157, 'AV-SB-02', '핀치 새장을 두기 알맞은 곳은?', '에어컨 바람이 바로 닿는 곳', '하루 종일 햇빛이 드는 창가', '직접 바람이나 햇빛이 닿지 않는 따뜻한 곳', '부엌 가스레인지 옆', 3, '작은 새는 외풍과 급격한 온도 변화에 약합니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (158, 'AV-SB-02', '알을 낳는 시기의 핀치에게 칼슘을 보충해 주는 방법은?', '설탕을 준다', '커틀본(갑오징어 뼈)이나 칼슘 보충제를 넣어 준다', '소금을 준다', '보충할 필요 없다', 2, '알을 만들 때 칼슘이 많이 쓰여 부족해지기 쉽습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (159, 'AV-SB-02', '핀치 발톱이 너무 길게 자라지 않게 하는 방법은?', '굵기가 다양한 횃대를 넣어 준다', '횃대를 모두 없앤다', '매일 발을 물에 담근다', '방법이 없다', 1, '굵기가 다른 횃대를 오가면 발톱이 자연스럽게 닳고 발 건강에도 좋습니다.');
INSERT INTO quiz (quizid, productid, question, choice1, choice2, choice3, choice4, answer, explanation) VALUES (160, 'AV-SB-02', '핀치를 키우는 방에서 피해야 할 것은?', '담배 연기, 향, 스프레이', '깨끗한 공기', '적당한 환기', '조용한 환경', 1, '새의 호흡기는 매우 예민해 연기나 스프레이에 쉽게 손상됩니다.');
